END;
$$;


--
-- Name: monitor_settings_enforce_override_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.monitor_settings_enforce_override_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_policy text;
BEGIN
    IF NEW.company_id IS NOT NULL THEN
        -- 同 key 的母版行优先于平台默认行。
        SELECT d.override_policy
          INTO v_policy
          FROM public.monitor_settings d
         WHERE d.deleted_at IS NULL
           AND d.company_id IS NULL
           AND d.key = NEW.key
           AND (d.tenant_id = NEW.tenant_id OR d.tenant_id IS NULL)
         ORDER BY (d.tenant_id IS NULL)
         LIMIT 1;

        IF v_policy = 'platform_only' THEN
            RAISE EXCEPTION '参数 % 的母版/平台策略为 platform_only，公司行不可覆盖', NEW.key
                USING ERRCODE = 'insufficient_privilege',
                      HINT = '请由平台运维放开 override_policy 后再写公司行';
        END IF;
    END IF;

    RETURN NEW;
END
$$;


--
-- Name: system_settings_enforce_override_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_settings_enforce_override_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_policy text;
BEGIN
    IF NEW.company_id IS NOT NULL THEN
        -- 同 key 的母版行优先于平台默认行。
        SELECT d.override_policy
          INTO v_policy
          FROM public.system_settings d
         WHERE d.deleted_at IS NULL
           AND d.company_id IS NULL
           AND d.key = NEW.key
           AND (d.tenant_id = NEW.tenant_id OR d.tenant_id IS NULL)
         ORDER BY (d.tenant_id IS NULL)
         LIMIT 1;

        IF v_policy = 'platform_only' THEN
            RAISE EXCEPTION '参数 % 的母版/平台策略为 platform_only，公司行不可覆盖', NEW.key
                USING ERRCODE = 'insufficient_privilege',
                      HINT = '请由平台运维放开 override_policy 后再写公司行';
        END IF;
    END IF;

    RETURN NEW;
END
$$;


--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pg_attribute
        WHERE attrelid = TG_RELID AND attname = 'updated_at' AND NOT attisdropped
    ) THEN
        NEW.updated_at := CURRENT_TIMESTAMP;
    END IF;
    RETURN NEW;
END $$;


