--
-- Name: org_stats; Type: MATERIALIZED VIEW; Schema: bi; Owner: -
--

CREATE MATERIALIZED VIEW bi.org_stats AS
 SELECT ( SELECT count(*) AS count
           FROM hrm.companies
          WHERE (companies.deleted_at IS NULL)) AS companies,
    ( SELECT count(*) AS count
           FROM hrm.departments
          WHERE (departments.deleted_at IS NULL)) AS departments,
    ( SELECT count(*) AS count
           FROM hrm.employees
          WHERE (employees.deleted_at IS NULL)) AS employees,
    now() AS refreshed_at
  WITH NO DATA;


