--
-- Name: purchase_orders purchase_orders_company_read; Type: POLICY; Schema: erp; Owner: -
--

CREATE POLICY purchase_orders_company_read ON erp.purchase_orders FOR SELECT USING (((tenant_id = erp.group_tenant_of((NULLIF(current_setting('app.tenant_id'::text, true), ''::text))::uuid)) AND (((company_id IS NOT NULL) AND ((company_id = erp.current_company_id()) OR erp.company_readable(company_id))) OR ((company_id IS NULL) AND (COALESCE(current_setting('app.actor_is_parent'::text, true), 'off'::text) = 'on'::text)))));


