--
-- Name: core_ticket_activities rls_tenant_isolation; Type: POLICY; Schema: ticket; Owner: -
--

CREATE POLICY rls_tenant_isolation ON ticket.core_ticket_activities USING (((COALESCE(current_setting('app.rls_system'::text, true), 'off'::text) = 'on'::text) OR (EXISTS ( SELECT 1
   FROM ticket.core_tickets p
  WHERE ((p.id = core_ticket_activities.ticket_id) AND (p.tenant_id = (NULLIF(current_setting('app.tenant_id'::text, true), ''::text))::uuid)))))) WITH CHECK (((COALESCE(current_setting('app.rls_system'::text, true), 'off'::text) = 'on'::text) OR (EXISTS ( SELECT 1
   FROM ticket.core_tickets p
  WHERE ((p.id = core_ticket_activities.ticket_id) AND (p.tenant_id = (NULLIF(current_setting('app.tenant_id'::text, true), ''::text))::uuid))))));


--
-- Name: core_ticket_comments rls_tenant_isolation; Type: POLICY; Schema: ticket; Owner: -
--

